internal sealed record LiveAudioRuntimePlanV1
{
 internal LiveAudioRuntimePlanV1(LiveAudioPlanId planId,Hash256 planHash,uint compilerVersion,Hash256 providerCatalogHash,IEnumerable<ParticipantDescriptorV1> participants,LoweredConstraintSetV1 constraints,IEnumerable<CapacityChargeTemplateV1> chargeTemplates,Hash256 applicabilityManifestHash,SchemaReferenceV1 privacyPolicyReference,Hash256 supportManifestReference)
 {ArgumentNullException.ThrowIfNull(participants);ArgumentNullException.ThrowIfNull(chargeTemplates);var p=participants.ToArray();var c=chargeTemplates.ToArray();if(!planId.IsValid||!Valid(planHash)||!Valid(providerCatalogHash)||p.Length>256||!ParticipantsStrict(p)||constraints is null||c.Length>256||!ChargesStrict(c)||!Valid(applicabilityManifestHash)||!privacyPolicyReference.IsValid||!Valid(supportManifestReference))throw new ArgumentException("Invalid live audio runtime plan.");PlanId=planId;PlanHash=planHash;CompilerVersion=compilerVersion;ProviderCatalogHash=providerCatalogHash;Participants=Array.AsReadOnly(p);Constraints=constraints;ChargeTemplates=Array.AsReadOnly(c);ApplicabilityManifestHash=applicabilityManifestHash;PrivacyPolicyReference=privacyPolicyReference;SupportManifestReference=supportManifestReference;}
 internal LiveAudioPlanId PlanId{get;}internal Hash256 PlanHash{get;}internal uint CompilerVersion{get;}internal Hash256 ProviderCatalogHash{get;}internal IReadOnlyList<ParticipantDescriptorV1> Participants{get;}internal LoweredConstraintSetV1 Constraints{get;}internal IReadOnlyList<CapacityChargeTemplateV1> ChargeTemplates{get;}internal Hash256 ApplicabilityManifestHash{get;}internal SchemaReferenceV1 PrivacyPolicyReference{get;}internal Hash256 SupportManifestReference{get;}
